    while (continuer == 0) {
        if (str[i] >= 'A' && str[i] <= 'Z')
            continuer = 1;
        if (str[i] >= 'a' && str[i] <= 'z') {
            str[i] = str[i] - 32;
            continuer = 1;
        }
        i++;
    }
    return (str);
}

